package org.lira.receiver;
import org.json.*;
import java.util.*;
/** Deterministic single-owner task runner. All external completions are generation fenced. */
public final class DictationEngine {
 /** busy must be a nonblocking snapshot; transport callbacks must never acquire engine locks. */
 public interface ExplanationAudio {boolean busy();JSONObject request(String path,JSONObject data)throws Exception;}
 private ExplanationAudio explanation;
 public synchronized void setExplanationAudio(ExplanationAudio value){explanation=value;if(v2!=null)v2.setExplanationAudio(value);}
 public synchronized JSONObject explanationAudio(String path,JSONObject data)throws Exception{
  if(explanation==null)throw new IllegalStateException("audio_unavailable");
  if(active()){
   // Stop remains available to the owned stream even after cancellation/recovery.
   if(!path.equals("/audio/stop")){if(v2==null)throw new IllegalStateException("dictation_owns_audio");v2.prepareExplanation(path.equals("/audio/start"));}
  }
  return explanation.request(path,data);
 }
 public interface Clock {long now();}
 public interface Audio {void play(String task,String hash,String asset,int repeats,Completion done);void stop();}
 public interface Completion {void done(boolean drained);}
 public interface Display {void show(String kind,JSONArray words,String text);}
 private final Clock clock;private final Audio audio;private final Display display;private final DictationStateStore store;private final TaskAssetStore assets;
 private int displayWidth=1920,displayHeight=1080;
 public synchronized void displaySize(int width,int height){displayWidth=width;displayHeight=height;if(v2!=null)v2.displaySize(width,height);}
 private boolean debugEnabled=false;private DictationEngineV2 v2; private JSONObject state;private Exception fatal;private JSONArray steps=new JSONArray();private long generation,deadline,remaining;private boolean audioDone;
 public DictationEngine(Clock c,Audio a,Display d,DictationStateStore s,TaskAssetStore cache)throws Exception {clock=c;audio=a;display=d;store=s;assets=cache;state=s.load();if(state!=null&&state.optInt("schema_version")==2){v2=new DictationEngineV2(c,a,d,s,cache,state);state=null;return;}if(state!=null){steps=state.getJSONArray("steps");if(active()){state.put("state","paused_recovery");/* Callback epoch is task-bound; generation alone fences process-local work. */event("paused",null);}}}
 public synchronized boolean active(){if(v2!=null)return v2.active();return state!=null&&!Arrays.asList("completed","cancelled","failed").contains(state.optString("state"));}
 public synchronized JSONObject status()throws Exception{if(v2!=null)return v2.status();return state==null?new JSONObject().put("state","idle"):new JSONObject(state.toString());}
 public synchronized JSONArray pendingEvents()throws Exception{if(v2!=null)return v2.status().getJSONArray("events");return state==null?new JSONArray():new JSONArray(state.getJSONArray("events").toString());}
 public synchronized void ack(String id)throws Exception {if(state==null)return;JSONArray old=state.getJSONArray("events"),next=new JSONArray();for(int i=0;i<old.length();i++)if(!old.getJSONObject(i).getString("event_id").equals(id))next.put(old.get(i));state.put("events",next);store.save(state);if(next.length()==0&&!active()){JSONObject t=state.getJSONObject("task");assets.release(t.getString("task_id"),t.getString("content_hash"));}}
 public synchronized JSONObject events(JSONObject data)throws Exception{if(v2==null)throw new IllegalArgumentException("v2_required");return v2.events(data);}
 public synchronized JSONObject ack(JSONObject data)throws Exception{if(v2==null)throw new IllegalArgumentException("v2_required");return v2.ack(data);}
 public synchronized JSONObject lease(JSONObject data)throws Exception{if(v2==null)throw new IllegalArgumentException("v2_required");return v2.lease(data);}
 public synchronized JSONObject localControl(String action)throws Exception{if(v2==null)throw new IllegalArgumentException("v2_required");return v2.localControl(action);}
 public synchronized void setDebug(boolean value)throws Exception{debugEnabled=value;if(v2!=null)v2.setDebug(value);}
 public synchronized void toggleDebug()throws Exception{if(v2!=null)v2.toggleDebug();}
 public synchronized void renderCurrent()throws Exception{if(v2!=null)v2.render();}
 private void event(String kind,String lesson)throws Exception {long rev=state.optLong("state_revision")+1,seq=state.optLong("sequence")+1;state.put("state_revision",rev).put("sequence",seq);JSONObject e=new JSONObject().put("task_id",state.getJSONObject("task").getString("task_id")).put("event_id",UUID.randomUUID().toString()).put("run_epoch",state.getInt("run_epoch")).put("sequence",seq).put("state_revision",rev).put("kind",kind).put("lesson_id",lesson==null?JSONObject.NULL:lesson).put("content_hash",state.getJSONObject("task").getString("content_hash"));state.getJSONArray("events").put(e);if(state.getJSONArray("events").length()>12000)throw new IllegalStateException("outbox full");store.save(state);}
 private void validateManifest(JSONObject task,JSONObject manifest)throws Exception {if(!task.getString("task_id").equals(manifest.getString("task_id"))||!task.getString("content_hash").equals(manifest.getString("content_hash")))throw new IllegalArgumentException("manifest scope");Set<String> found=new HashSet<>();JSONArray list=manifest.getJSONArray("assets");for(int i=0;i<list.length();i++){JSONObject x=list.getJSONObject(i);String id=x.getString("asset_id");if(!found.add(id)||x.getInt("sample_rate")!=24000||x.getInt("channels")!=1||x.getLong("frames")*2!=x.getLong("pcm_bytes"))throw new IllegalArgumentException("asset descriptor");if(!assets.begin(task.getString("task_id"),task.getString("content_hash"),id,x.getLong("pcm_bytes"),x.getString("sha256")))throw new IllegalArgumentException("asset not ready");}Set<String> required=new HashSet<>(Arrays.asList("prompt.prepare","prompt.finish","prompt.pinyin"));JSONArray lessons=task.getJSONArray("lessons");for(int n=0;n<lessons.length();n++){JSONObject l=lessons.getJSONObject(n);JSONArray words=l.getJSONArray("expanded_words");for(int j=0;j<words.length();j++)required.add(words.getJSONObject(j).getString("audio_asset_id"));if(!l.isNull("recitation"))required.add(l.getJSONObject("recitation").getString("prompt_audio_asset_id"));}if(!found.containsAll(required))throw new IllegalArgumentException("missing required assets");}
 private void add(String kind,String lesson,JSONArray words,String asset,long seconds)throws Exception {steps.put(new JSONObject().put("kind",kind).put("lesson_id",lesson==null?JSONObject.NULL:lesson).put("words",words).put("asset",asset).put("seconds",seconds));}
 public synchronized JSONObject start(JSONObject wrapper)throws Exception {if(explanation!=null&&explanation.busy())throw new IllegalStateException("explanation_audio_busy");if(wrapper.getJSONObject("task").optInt("schema_version")==2){if(v2==null){if(state!=null&&(active()||state.getJSONArray("events").length()>0))throw new IllegalStateException("legacy_busy");v2=new DictationEngineV2(clock,audio,display,store,assets,null);v2.displaySize(displayWidth,displayHeight);v2.setExplanationAudio(explanation);v2.setDebug(debugEnabled);}return v2.start(wrapper);}if(v2!=null)throw new IllegalStateException("v2_receipt_retained");JSONObject task=DictationSpec.parse(wrapper.getJSONObject("task")).task;String id=task.getString("task_id");JSONArray history=state==null?new JSONArray():state.optJSONArray("history");if(history==null)history=new JSONArray();for(int h=0;h<history.length();h++){JSONObject previous=history.getJSONObject(h);if(previous.getString("task_id").equals(id)){if(!previous.getString("content_hash").equals(task.getString("content_hash")))throw new IllegalArgumentException("retired task conflict");return new JSONObject().put("task",task).put("state",previous.getString("state")).put("state_revision",previous.getLong("state_revision")).put("retired",true);}}if(state!=null&&state.getJSONObject("task").getString("task_id").equals(id)){if(!state.getJSONObject("task").getString("content_hash").equals(task.getString("content_hash")))throw new IllegalArgumentException("task conflict");return status();}if(active()||(state!=null&&state.getJSONArray("events").length()>0))throw new IllegalStateException("task or pending callbacks busy");validateManifest(task,wrapper.getJSONObject("manifest"));if(state!=null){if(history.length()>=1000)throw new IllegalStateException("task receipt capacity");JSONObject previous=state.getJSONObject("task");history.put(new JSONObject().put("task_id",previous.getString("task_id")).put("content_hash",previous.getString("content_hash")).put("state",state.getString("state")).put("state_revision",state.getLong("state_revision")));}steps=new JSONArray();JSONObject p=task.getJSONObject("parameters");add("prepare",null,new JSONArray(),"prompt.prepare",0);JSONArray ls=task.getJSONArray("lessons");for(int i=0;i<ls.length();i++){JSONObject l=ls.getJSONObject(i);JSONArray w=l.getJSONArray("expanded_words");for(int j=0;j<w.length();j++){JSONObject word=w.getJSONObject(j);if(word.getJSONArray("pinyin_required_for").length()>0)add("instruction",l.getString("lesson_id"),new JSONArray(),"prompt.pinyin",0);add("expanded",l.getString("lesson_id"),new JSONArray().put(word),word.getString("audio_asset_id"),p.getInt("expanded_word_seconds"));}}for(int i=0;i<ls.length();i++){JSONObject l=ls.getJSONObject(i);JSONArray pages=WordPageLayout.pages(l.getJSONArray("recognition_words"),displayWidth,displayHeight);for(int j=0;j<pages.length();j++){JSONArray page=pages.getJSONArray(j);int characters=0;for(int k=0;k<page.length();k++){String word=page.getJSONObject(k).getString("text");characters+=word.codePointCount(0,word.length());}add("recognition",l.getString("lesson_id"),page,"",characters*p.getInt("recognition_seconds_per_character"));}}for(int i=0;i<ls.length();i++){JSONObject l=ls.getJSONObject(i);if(!l.isNull("recitation"))add("recitation",l.getString("lesson_id"),new JSONArray(),l.getJSONObject("recitation").getString("prompt_audio_asset_id"),0);}add("finish",null,new JSONArray(),"prompt.finish",0);state=new JSONObject().put("history",history).put("task",task).put("manifest",wrapper.getJSONObject("manifest")).put("steps",steps).put("index",0).put("state","running").put("run_epoch",1).put("sequence",0).put("state_revision",0).put("events",new JSONArray()).put("done",new JSONArray()).put("counted",new JSONArray()).put("commands",new JSONObject());event("created",null);event("started",null);enter();return status();}
 private JSONObject current()throws Exception{return steps.getJSONObject(state.getInt("index"));}
 private void enter()throws Exception {final long token=++generation;audioDone=false;deadline=0;JSONObject step=current();String kind=step.getString("kind");JSONArray words=step.getJSONArray("words");display.show(kind,kind.equals("expanded")?new JSONArray():words,kind.equals("prepare")?"准备开始默写":kind.equals("finish")?"默写时间到，默写完成":kind.equals("expanded")?"请听写词语":kind.equals("instruction")?"请为本词指定字标注拼音":kind.equals("recitation")?"请背诵课文":"请看字写拼音");long duration=step.getLong("seconds")*1000;if(remaining>0)duration=remaining;remaining=0;final long wait=duration;JSONObject params=state.getJSONObject("task").getJSONObject("parameters");if(params.getString("expanded_timer_anchor").equals("from_item_start")&&kind.equals("expanded"))deadline=clock.now()+wait;String asset=step.getString("asset");if(asset.isEmpty()){audioDone=true;deadline=clock.now()+wait;}else {JSONObject t=state.getJSONObject("task");audio.play(t.getString("task_id"),t.getString("content_hash"),asset,kind.equals("expanded")?params.getInt("expanded_repeat_count"):1,new Completion(){public void done(boolean drained){synchronized(DictationEngine.this){if(generation!=token||!state.optString("state").equals("running"))return;try{if(!drained){pause("audio_failure");return;}audioDone=true;if(deadline==0)deadline=clock.now()+wait;tick();}catch(Exception e){fatal=e;generation++;audio.stop();try{state.put("state","failed");event("failed",null);}catch(Exception ignored){}}}}});}store.save(state);}
 public synchronized void tick()throws Exception {if(v2!=null){v2.tick();return;}if(state==null||!state.optString("state").equals("running")||!audioDone)return;String kind=current().getString("kind");if(kind.equals("recitation"))return;if((kind.equals("prepare")||kind.equals("finish")||kind.equals("instruction"))||(state.getJSONObject("task").getJSONObject("parameters").getString("advance_mode").equals("automatic")&&clock.now()>=deadline))complete();}
 private boolean has(JSONArray a,Object value)throws Exception {for(int i=0;i<a.length();i++)if(a.get(i).equals(value))return true;return false;}
 private void complete()throws Exception {int index=state.getInt("index");JSONObject step=current();JSONArray done=state.getJSONArray("done");if(!has(done,index))done.put(index);String lesson=step.isNull("lesson_id")?null:step.getString("lesson_id");if(step.getString("kind").equals("recitation"))event("recitation_completed",lesson);if(lesson!=null){boolean all=true;for(int i=0;i<steps.length();i++){JSONObject s=steps.getJSONObject(i);if(s.optString("lesson_id").equals(lesson)&&!s.getString("kind").equals("recitation")&&!has(done,i))all=false;}if(all&&!has(state.getJSONArray("counted"),lesson)){state.getJSONArray("counted").put(lesson);event("lesson_dictation_completed",lesson);}}advance();}
 private void advance()throws Exception {generation++;audio.stop();if(state.getInt("index")+1>=steps.length()){state.put("state","completed");event("task_completed",null);return;}state.put("index",state.getInt("index")+1);event("progress",null);enter();}
 public synchronized void pause(String reason)throws Exception {if(v2!=null){v2.pause(reason);return;}if(!active()||!state.getString("state").equals("running"))return;remaining=deadline==0?current().getLong("seconds")*1000:Math.max(1,deadline-clock.now());generation++;audio.stop();state.put("state","paused").put("pause_reason",reason).put("remaining",remaining);event("paused",null);JSONObject step=current();display.show("paused",step.getString("kind").equals("recognition")?step.getJSONArray("words"):new JSONArray(),"已暂停，按继续恢复");}
 public synchronized JSONObject control(JSONObject request)throws Exception {if(v2!=null)return v2.control(request);if(state==null||!request.getString("task_id").equals(state.getJSONObject("task").getString("task_id")))throw new IllegalArgumentException("task mismatch");String id=DictationSpec.text(request.get("command_id"),128,true),command=request.getString("command");JSONObject commands=state.getJSONObject("commands");String fingerprint=DictationSpec.canonical(request);if(commands.has(id)){if(!commands.getString(id).equals(fingerprint))throw new IllegalArgumentException("command conflict");return status();}if(request.getLong("expected_state_revision")!=state.getLong("state_revision"))throw new IllegalArgumentException("stale revision");if(!active())throw new IllegalArgumentException("task terminal");if(commands.length()>=4096)throw new IllegalArgumentException("command limit");commands.put(id,fingerprint);if(!Arrays.asList("pause","previous","continue","next","skip","replay","recitation_complete","cancel").contains(command)){commands.remove(id);throw new IllegalArgumentException("unknown command");}if(command.equals("pause"))pause("control");else if(command.equals("previous")){pause("previous");remaining=0;state.put("remaining",0).put("index",Math.max(0,state.getInt("index")-1));event("progress",null);JSONObject previous=current();display.show("paused",previous.getString("kind").equals("recognition")?previous.getJSONArray("words"):new JSONArray(),"已暂停，按继续恢复");}else if(command.equals("continue")){validateManifest(state.getJSONObject("task"),state.getJSONObject("manifest"));if(!state.getString("state").equals("running")){if(state.getJSONObject("task").getJSONObject("parameters").getString("resume_timer_policy").equals("remaining"))remaining=state.optLong("remaining");else remaining=0;state.put("state","running");event("resumed",null);enter();}}else if(command.equals("next")){if(!audioDone||!state.getString("state").equals("running")||current().getString("kind").equals("recitation")){commands.remove(id);throw new IllegalArgumentException("not ready");}complete();}else if(command.equals("skip")){advance();}else if(command.equals("replay")){pause("replay");state.put("state","running");event("resumed",null);enter();}else if(command.equals("recitation_complete")){if(!current().getString("kind").equals("recitation")||!audioDone||!state.getString("state").equals("running")){commands.remove(id);throw new IllegalArgumentException("not recitation");}String mode=state.getJSONObject("task").getJSONObject("parameters").getString("recitation_end_mode");if(!request.optString("source").equals(mode)){commands.remove(id);throw new IllegalArgumentException("recitation signal source");}complete();}else if(command.equals("cancel")){generation++;audio.stop();state.put("state","cancelled");event("cancelled",null);}else throw new IllegalArgumentException("unknown command");store.save(state);return status();}
}
